-- Reposiciona las secuencias de identidad de todas las tablas que recibieron
-- filas con identificadores explícitos (datos de prueba, documento
-- database/seeds/001_datos_prueba.sql). Con GENERATED BY DEFAULT AS IDENTITY,
-- un INSERT con id explícito no avanza la secuencia: sin este ajuste, el
-- primer id generado por la columna identity chocaría con los ids sembrados.
-- Aplicado sobre aulasmart_test, los ids generados parten de justo después
-- del bloque de filas sintéticas. La operación es idempotente: siempre
-- recalcula el punto de partida a partir del máximo id vigente.
BEGIN;

SELECT setval(
    pg_get_serial_sequence('aula', 'id_aula'),
    (SELECT COALESCE(MAX(id_aula) + 1, 1) FROM aula),
    false
);

SELECT setval(
    pg_get_serial_sequence('edificio', 'id_edificio'),
    (SELECT COALESCE(MAX(id_edificio) + 1, 1) FROM edificio),
    false
);

SELECT setval(
    pg_get_serial_sequence('tipo_aula', 'id_tipo_aula'),
    (SELECT COALESCE(MAX(id_tipo_aula) + 1, 1) FROM tipo_aula),
    false
);

SELECT setval(
    pg_get_serial_sequence('dependencia', 'id_dependencia'),
    (SELECT COALESCE(MAX(id_dependencia) + 1, 1) FROM dependencia),
    false
);

SELECT setval(
    pg_get_serial_sequence('sincronizacion_siga', 'id_sincronizacion'),
    (SELECT COALESCE(MAX(id_sincronizacion) + 1, 1) FROM sincronizacion_siga),
    false
);

SELECT setval(
    pg_get_serial_sequence('usuario', 'id_usuario'),
    (SELECT COALESCE(MAX(id_usuario) + 1, 1) FROM usuario),
    false
);

SELECT setval(
    pg_get_serial_sequence('rol', 'id_rol'),
    (SELECT COALESCE(MAX(id_rol) + 1, 1) FROM rol),
    false
);

SELECT setval(
    pg_get_serial_sequence('horario_academico', 'id_horario'),
    (SELECT COALESCE(MAX(id_horario) + 1, 1) FROM horario_academico),
    false
);

SELECT setval(
    pg_get_serial_sequence('solicitud_aula', 'id_solicitud'),
    (SELECT COALESCE(MAX(id_solicitud) + 1, 1) FROM solicitud_aula),
    false
);

COMMIT;
